// Round-bottom flask support ring on three legs
// Print orientation: legs on the bed (z = 0), ring on top.

// ---------- Parameters ----------
ring_od        = 90;   // ring outer diameter (mm)
ring_id        = 66;   // ring inner diameter (mm)
ring_thick     = 5;    // ring thickness (mm)
ring_top_z     = 40;   // height of ring top face (mm)

leg_d          = 6;    // leg diameter (mm)
leg_circle_d   = 78;   // diameter of circle the leg axes lie on (mm)
leg_count      = 3;    // number of legs
leg_start_ang  = 0;    // angle of first leg (deg, 0 = +X axis)
leg_overlap    = 1;    // leg extension into ring for a solid union (mm)

eps            = 0.5;  // cutter overshoot for clean differences (mm)
$fn            = 128;  // curve resolution

// ---------- Derived ----------
ring_bot_z = ring_top_z - ring_thick;   // ring bottom face z (35 mm)
leg_h      = ring_bot_z + leg_overlap;  // leg height from bed into ring

// ---------- Model ----------
union() {
    // Flat annular ring
    translate([0, 0, ring_bot_z])
        difference() {
            cylinder(d = ring_od, h = ring_thick);
            translate([0, 0, -eps])
                cylinder(d = ring_id, h = ring_thick + 2 * eps);
        }

    // Three vertical legs, 120 degrees apart
    for (i = [0 : leg_count - 1])
        rotate([0, 0, leg_start_ang + i * 360 / leg_count])
            translate([leg_circle_d / 2, 0, 0])
                cylinder(d = leg_d, h = leg_h, $fn = 64);
