```openscad
// Round-bottom flask support ring with three legs
// Units: mm. Print orientation: legs on bed (z = 0), ring on top.

$fn = 96;

// ---- Ring ----
ring_od        = 70;    // outer diameter of ring
ring_id        = 54;    // inner diameter of ring (flask seat opening)
ring_thick     = 6;     // ring thickness (Z)
ring_top_z     = 40;    // Z height of ring top face

// ---- Legs ----
leg_d          = 8;     // leg diameter
leg_circle_d   = 62;    // diameter of circle on which leg axes lie
leg_count      = 3;     // number of legs
leg_start_ang  = 0;     // first leg on +X axis (degrees)
leg_overlap    = 0.5;   // legs extend into ring to fuse solidly

// ---- Derived ----
ring_bottom_z  = ring_top_z - ring_thick;
cut_eps        = 0.5;   // extension of cutters past faces

union() {
    // Flat annular ring
    difference() {
        translate([0, 0, ring_bottom_z])
            cylinder(d = ring_od, h = ring_thick);
        translate([0, 0, ring_bottom_z - cut_eps])
            cylinder(d = ring_id, h = ring_thick + 2 * cut_eps);
    }

    // Three legs from bed up into ring
    for (i = [0 : leg_count - 1]) {
        a = leg_start_ang + i * 360 / leg_count;
        translate([leg_circle_d / 2 * cos(a), leg_circle_d / 2 * sin(a), 0])
            cylinder(d = leg_d, h = ring_bottom_z + leg_overlap);
    }
}
