// Spacer for raising a circuit board, with a sunk socket-head screw
// Print orientation: standing on the bed, z = 0 to 15, centred on origin

$fn = 96;               // curve resolution

// --- Dimensions (mm) ---
body_d      = 18;       // outer diameter of spacer
body_h      = 15;       // total height of spacer
hole_d      = 4.5;      // through-hole diameter (screw clearance)
cbore_d     = 8;        // counterbore diameter (socket head)
cbore_depth = 4;        // counterbore depth from top face (z = 11 to 15)
eps         = 0.5;      // overcut so cutting faces are not coplanar

difference() {
    // Main cylindrical body
    cylinder(d = body_d, h = body_h);

    // Through-hole along the axis
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = body_h + 2 * eps);

    // Coaxial counterbore from the top face
    translate([0, 0, body_h - cbore_depth])
        cylinder(d = cbore_d, h = cbore_depth + eps);
}
```

