```openscad
// Sliding mount with dovetail rail
// Print orientation: base plate flat on the bed, rail pointing up (+Z)

$fn = 64;

// ---------------- Dimensions (mm) ----------------
plate_len   = 80;   // base plate length (X)
plate_wid   = 30;   // base plate width (Y)
plate_thk   = 6;    // base plate thickness (Z), z = 0..6

rail_len    = plate_len; // rail runs the full plate length (X)
rail_w_bot  = 10;   // rail width where it meets the plate (at z = plate_thk)
rail_w_top  = 14;   // rail width at its top face
rail_top_z  = 14;   // absolute Z of rail top face
rail_h      = rail_top_z - plate_thk; // rail height above plate (8 mm)

overlap     = 0.01; // small overlap so rail fuses into plate (no coplanar faces)

// ---------------- Modules ----------------
module base_plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

// Dovetail cross-section drawn in a local 2D plane (u = Y, v = Z),
// then extruded along X.
module dovetail_rail() {
    rotate([90, 0, 90])               // local X->Y, local Y->Z, extrusion Z->X
        linear_extrude(height = rail_len, center = true)
            polygon(points = [
                [-rail_w_bot/2, plate_thk - overlap], // bottom-left (dips into plate)
                [ rail_w_bot/2, plate_thk - overlap], // bottom-right
                [ rail_w_bot/2, plate_thk],           // bottom-right at plate surface
                [ rail_w_top/2, rail_top_z],          // top-right
                [-rail_w_top/2, rail_top_z],          // top-left
                [-rail_w_bot/2, plate_thk]            // bottom-left at plate surface
            ]);
}

// ---------------- Assembly ----------------
union() {
    base_plate();
    dovetail_rail();
}
```

```openscad
// Sliding mount with dovetail rail
// Print orientation: base plate on bed (z = 0), rail building upward (+Z)

$fn = 64;

// ---- Base plate ----
plate_len   = 120;   // plate length along X (mm)
plate_wid   = 40;    // plate width along Y (mm)
plate_thk   = 4;     // plate thickness (z = 0 to 4)

// ---- Dovetail rail ----
rail_len    = plate_len; // rail runs full plate length (mm)
rail_w_bot  = 14;    // rail width where it meets the plate at z = 4 (mm)
rail_w_top  = 18;    // rail width at its top face (mm)
rail_z_top  = 12;    // height of rail top face above bed (mm)
overlap     = 0.5;   // rail sinks into plate to fuse solids (mm)

// Rail half-width at a given z (linear flare from bottom to top)
function rail_half_w(z) =
    (rail_w_bot + (rail_w_top - rail_w_bot) *
     (z - plate_thk) / (rail_z_top - plate_thk)) / 2;

union() {
    // Base plate, centred in X and Y
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Dovetail rail: trapezoid in YZ, extruded along X
    rotate([90, 0, 90])
        linear_extrude(height = rail_len, center = true)
            polygon(points = [
                [-rail_half_w(plate_thk - overlap), plate_thk - overlap],
                [ rail_half_w(plate_thk - overlap), plate_thk - overlap],
                [ rail_w_top/2,                     rail_z_top],
                [-rail_w_top/2,                     rail_z_top]
            ]);
}
