// Weighted base for a lab stand rod
// Print orientation: disc flat on the bed, boss pointing up (+Z)

$fn = 128;

// --- Base disc ---
disc_d = 120;      // disc diameter
disc_h = 8;        // disc thickness (z = 0 to 8)

// --- Boss ---
boss_d = 30;       // boss diameter
boss_h = 20;       // boss height above disc (z = 8 to 28)

// --- Rod hole ---
hole_d = 10.5;     // rod hole diameter
floor_t = 2;       // closed floor thickness under the hole (hole stops at z = 2)

// --- Derived ---
total_h = disc_h + boss_h;   // top of boss (z = 28)
eps = 0.5;                   // cutter overshoot past top face

difference() {
    union() {
        // Base disc
        cylinder(d = disc_d, h = disc_h);
        // Boss (overlaps slightly into disc for a clean union)
        translate([0, 0, disc_h - 0.01])
