// Door wedge with vertical through-slot
// Units: mm. Print orientation: flat bottom on the XY plane (z = 0).
// Placed in the user's coordinates: x = 0..120, y = 0..40, z = 0..20.

$fn = 64;

// ---------------- Wedge dimensions ----------------
wedge_length = 120;   // X length of wedge (tip is at x = wedge_length)
wedge_width  = 40;    // Y width of wedge (extrusion depth)
wedge_height = 20;    // Z height at the tall end (x = 0)

// ---------------- Slot dimensions ----------------
slot_width    = 6;    // slot size in Y
slot_length   = 30;   // slot size in X
slot_center_x = 60;   // slot centre position in X
slot_center_y = 20;   // slot centre position in Y

// ---------------- Cutting clearance ----------------
eps = 1;              // extension of cutters past the faces they cut

// ---------------- Model ----------------
difference() {
    // Right-triangle cross-section in XZ, extruded along Y from y = 0 to y = wedge_width
    translate([0, wedge_width, 0])
        rotate([90, 0, 0])
            linear_extrude(height = wedge_width)
                polygon(points = [
                    [0, 0],                    // (x = 0,   z = 0)
                    [wedge_length, 0],         // (x = 120, z = 0)
                    [0, wedge_height]          // (x = 0,   z = 20)
                ]);

    // Vertical straight slot through the whole wedge
    translate([slot_center_x - slot_length / 2,
               slot_center_y - slot_width / 2,
               -eps])
        cube([slot_length, slot_width, wedge_height + 2 * eps]);
}
