// Glass stirring rod rest - rectangular block with V-grooves across the top
// Print orientation: flat on bed, grooves facing up

// ---------------- Parameters ----------------
block_len     = 90;   // block length along X (mm)
block_wid     = 40;   // block width along Y (mm)
block_h       = 15;   // block height along Z (mm)

groove_count  = 5;    // number of V-grooves
groove_pitch  = 15;   // centre-to-centre spacing of grooves along X (mm)
groove_top_w  = 10;   // groove width at the top surface (mm)
groove_depth  = 5;    // groove depth (mm); 90-degree V since depth = width/2

eps           = 0.5;  // overshoot so cutters pass beyond the faces they cut

$fn = 64;

// ---------------- Derived ----------------
half_top = groove_top_w / 2;   // half-width at the top surface
first_x  = -(groove_count - 1) * groove_pitch / 2;  // X of first groove centre

// ---------------- Groove cutter ----------------
// V profile drawn in the X-Z plane, extruded along Y.
// The cutter is extended eps above the top face, keeping the 45-degree flanks,
// so the opening at the real top surface is exactly groove_top_w.
module v_groove() {
    rotate([90, 0, 0])
        linear_extrude(height = block_wid + 2 * eps, center = true)
            polygon(points = [
                [0,                   block_h - groove_depth],  // V bottom
                [ half_top + eps,     block_h + eps],          // top right
                [-(half_top + eps),   block_h + eps]           // top left
            ]);
}

// ---------------- Part ----------------
difference() {
    // Main block, centred in X and Y, resting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_h]);

    // V-grooves running full width along Y
    for (i = [0 : groove_count - 1])
        translate([first_x + i * groove_pitch, 0, 0])
            v_groove();
}
