    // along the 45-degree flanks so the 90-degree angle is preserved.
    polygon(points = [
        [0, block_h - groove_depth],                // apex (bottom of V)
        [ groove_half + eps, block_h + eps],        // right flank, above top
        [-(groove_half + eps), block_h + eps]       // left flank, above top
    ]);
}

module groove_cutter() {
    // Extrude profile along Y, running past both side faces
    rotate([90, 0, 0])
        linear_extrude(height = block_wid + 2 * eps, center = true)
            v_groove_profile();
}

