block_len   = 69;    // length along X (mm)
block_wid   = 30;    // width along Y (mm)
block_ht    = 15;    // height along Z (mm)

// ---- Groove dimensions ----
groove_count = 4;    // number of V-grooves
groove_pitch = 15;   // centre-to-centre spacing along X (mm)
groove_top_w = 10;   // groove width at top surface (mm)
groove_depth = 5;    // groove depth (mm) - 90 deg V: depth = top_w/2
cut_extra    = 0.5;  // overshoot past faces for clean cuts (mm)

$fn = 64;

// One V-groove cutter, centred on x = 0, running along Y
module v_groove() {
    // Extend the V above the top face while keeping the 90-degree angle
    hw = groove_top_w / 2 + cut_extra;   // half width at extended top
    rotate([90, 0, 0])
        linear_extrude(height = block_wid + 2 * cut_extra, center = true)
            polygon([
                [0,   block_ht - groove_depth],      // V bottom
                [ hw, block_ht + cut_extra],         // top right
                [-hw, block_ht + cut_extra]          // top left
            ]);
}

difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // Grooves, centred along X
    for (i = [0 : groove_count - 1])
        translate([(i - (groove_count - 1) / 2) * groove_pitch, 0, 0])
            v_groove();
}
