    for (i = [0 : groove_count - 1]) {
        x = (i - (groove_count - 1)/2) * groove_pitch;
        translate([x, 0, block_h])
            rotate([90, 0, 0])
                linear_extrude(height = block_wid + 2*eps, center = true)
                    groove_profile();
    }
