// Captive hex-nut clamping block
// Print orientation: bottom face (with hex pocket) on the bed at z = 0

// ---------------- Parameters ----------------
block_x      = 20;    // block length in X (mm)
block_y      = 20;    // block width in Y (mm)
block_z      = 10;    // block height in Z (mm)

hole_d       = 5.5;   // through-hole diameter (mm)

hex_flats    = 8.2;   // hex pocket size across the flats (mm)
hex_depth    = 4.2;   // hex pocket depth from the bottom face (mm)

eps          = 0.5;   // overshoot of cutting shapes past the faces they cut (mm)
fn_round     = 96;    // facet count for round holes

// Circumradius of the hexagon, from its across-flats size
hex_r = hex_flats / (2 * cos(30));

// ---------------- Model ----------------
difference() {
    // Main block, centred in X/Y, resting on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_z]);

    // Vertical through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = block_z + 2 * eps, $fn = fn_round);

    // Hex nut pocket from the bottom face.
    // cylinder() with $fn = 6 puts a vertex on the +X axis,
    // so two flats are parallel to the X axis (at y = +/- hex_flats/2).
    translate([0, 0, -eps])
        cylinder(r = hex_r, h = hex_depth + eps, $fn = 6);
}
