    // Plus-shaped plate
    union() {
        translate([-arm_len/2, -arm_w/2, 0]) cube([arm_len, arm_w, plate_t]);
        translate([-arm_w/2, -arm_len/2, 0]) cube([arm_w, arm_len, plate_t]);
    }

    // Centre hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2*eps);

    // Arm-end holes
    for (a = [0, 90, 180, 270])
        rotate([0, 0, a])
            translate([hole_off, 0, -eps])
                cylinder(d = hole_d, h = plate_t + 2*eps);
