// Cross-shaped bottle stabiliser
// Flat plus-sign plate lying on the bed, centred on the origin

// ---- Dimensions (mm) ----
plate_t      = 3;     // plate thickness (Z)
arm_len      = 70;    // overall length of each bar (X and Y)
arm_w        = 10;    // width of each bar
hole_d       = 5.5;   // diameter of all through-holes
hole_offset  = 30;    // distance of arm-end holes from origin
eps          = 0.5;   // overshoot for clean boolean cuts

$fn = 64;             // smoothness of curved shapes

difference() {
    // Plus-shaped plate
    union() {
        // Bar along X
        translate([-arm_len/2, -arm_w/2, 0])
            cube([arm_len, arm_w, plate_t]);
        // Bar along Y
        translate([-arm_w/2, -arm_len/2, 0])
            cube([arm_w, arm_len, plate_t]);
    }

    // Centre hole
