// Stepped riser - 5 equal steps climbing in +X
// Print orientation: resting on bed (z = 0), building upward.
// Placed at the user's coordinates: x = 0..75, y = 0..20.

// ---------------- Parameters ----------------
num_steps   = 5;     // number of steps
step_length = 15;    // length of each step along X (mm)
step_rise   = 8;     // height increase per step (mm)
riser_width = 20;    // extrusion depth along Y (mm)

total_length = num_steps * step_length;  // 75 mm
total_height = num_steps * step_rise;    // 40 mm

// ---------------- Profile (XZ plane) ----------------
// Staircase outline: along the bed, up the back face, then down each step.
profile_points = concat(
    [[0, 0], [total_length, 0]],
    [for (i = [num_steps - 1 : -1 : 0])
        each [[(i + 1) * step_length, (i + 1) * step_rise],
              [ i      * step_length, (i + 1) * step_rise]]]
);

// ---------------- Model ----------------
// The 2D profile is drawn in X/Y, then rotated so its Y becomes Z.
// rotate([90,0,0]) sends +extrusion to -Y, so shift by riser_width
// to occupy y = 0..20.
translate([0, riser_width, 0])
    rotate([90, 0, 0])
        linear_extrude(height = riser_width)
            polygon(points = profile_points);
