    for (i = [0 : num_steps - 1]) {
        // Step i spans x = i*15 to (i+1)*15 and is solid from z = 0 up to (i+1)*6.
        // Each block (except the last) extends slightly into the next block so the union fuses.
        translate([i * step_length, 0, 0])
            cube([step_length + (i < num_steps - 1 ? overlap : 0),
                  depth_y,
                  (i + 1) * step_rise]);
    }
}
