    // Lower block with sharp bottom edges and vertical sides
    translate([-base_x / 2, -base_y / 2, 0])
        cube([base_x, base_y, side_h]);

    // Chamfered top section: hull between the full footprint at z = side_h
    // and the reduced top face at z = base_z
    hull() {
        translate([-base_x / 2, -base_y / 2, side_h - thin])
            cube([base_x, base_y, thin]);
        translate([-top_x / 2, -top_y / 2, base_z - thin])
            cube([top_x, top_y, thin]);
    }
